CREATE TABLE training_requirements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,course_id UUID NOT NULL REFERENCES training_courses(id),department_id UUID REFERENCES departments(id),section_id UUID REFERENCES sections(id),position_id UUID REFERENCES positions(id),shift VARCHAR(100),location VARCHAR(255),employee_id UUID REFERENCES employees(id),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE training_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,year INT NOT NULL,department_id UUID REFERENCES departments(id),section_id UUID REFERENCES sections(id),status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE training_assignments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),employee_id UUID NOT NULL REFERENCES employees(id),course_id UUID NOT NULL REFERENCES training_courses(id),plan_id UUID REFERENCES training_plans(id),assigned_date DATE NOT NULL,due_date DATE,status VARCHAR(30) NOT NULL,UNIQUE(employee_id,course_id,due_date));CREATE INDEX idx_assignment_status_due ON training_assignments(status,due_date);